import { IGameServerResponse, SessionSettings, SessionStatus } from '@game-studio/server-comms';

import { EventEmitter } from 'eventemitter3';
import { gameConfig } from './config-model';
import { inversifyContainer } from '../inversify/container';
import { eventEmitter } from '../services/event-emitter';
import { queryStringParams } from '../services/query-string';
import { getLocaleString } from '../services/utilities';
import { userModel } from './user';

interface ISessionStatusEx extends SessionStatus {
    PgdaSessionId: string;
}

export interface ISessionDataEvents {
    sessionIdUpdated(sessionId: string): void;
    ticketIdUpdated(sessionId: string): void;
}

export class SessionDataModel {
    private _settingsText = {
        ticketId: {
            text: '0',
        },
        sessionId: {
            text: '0',
        },
    };

    public sessionDataEvents = new EventEmitter<ISessionDataEvents>();

    private _status: ISessionStatusEx = {
        AlertFrequency: 0,
        CurrentBet: 0,
        CurrentTime: 0,
        FunBonusConversionFailed: false,
        LimitApproaching: false,
        MaxBet: 0,
        MaxTime: 0,
        NetBalance: 0,
        PgdaSessionId: '',
        SessionEnded: true,
        SessionEndTime: 0,
        SessionId: 0,
        SessionRestriction: 0,
        StartBalance: 0,
        TotalWinnings: 0,
    };

    private _settings: SessionSettings = {
        ValidAlertFrequencies: [],
        ValidMaxBets: [],
        ValidMaxTimes: [],
        ValidSessionRestrictions: [],
    };

    public get settingsText() {
        return this._settingsText;
    }

    public get status() {
        return this._status;
    }

    public get settings() {
        return this._settings;
    }

    protected sessionToken: string;

    constructor() {
        eventEmitter.on('GLOBAL_SESSION_CREATED', this.onSessionCreated, this);
        if (queryStringParams.isSubGame) {
            eventEmitter.on('POPUP_SHOW_SESSION', (response) => {
                inversifyContainer.frameConnection.operator.onUserActionRequired({ type: 'session-manager', data: response });
            });
        }
    }

    /**
     * alidates the sessionData.status for if the session is complete
     * @returns true if the session is still valid false other wise (and shows the session manager)
     */
    public validateSession(): boolean {
        if (gameConfig.features.enableSessionManager) {
            if (sessionDataModel.status.SessionEnded && inversifyContainer.gameModel.isComplete !== false) {
                if (userModel.totalBalance.endBalance < inversifyContainer.stake.lowestStake && !inversifyContainer.cabinet.inFreePlay) {
                    eventEmitter.emit('GLOBAL_LOW_BALANCE', userModel.totalBalance.endBalance, inversifyContainer.stake.lowestStake);
                    return false;
                }
                eventEmitter.emit('POPUP_SHOW_SESSION', {
                    freePlayBalance: userModel.freePlayBalance,
                });
                return false;
            }

            return true;
        }

        return true;
    }

    public setData(response: IGameServerResponse): void;
    public setData(requestType: 'FromBingo', status?: Partial<SessionStatus>, settings?: Partial<SessionSettings>): void;
    public setData(arg1: IGameServerResponse | 'FromBingo', arg2?: Partial<SessionStatus>, arg3?: Partial<SessionSettings>): void {
        const requestType = typeof arg1 === 'string' ? arg1 : arg1.RequestType;
        const status = typeof arg1 === 'string' ? arg2 : arg1.SessionStatus;
        const settings = typeof arg1 === 'string' ? arg3 : arg1.SessionSettings;

        if (status) {
            this.setSessionStatus(status);
        }
        if (settings) {
            this.setSessionSettings(settings);
        }

        if (requestType === 'Resume') {
            if (!inversifyContainer.gameModel.isInProgress) {
                this._settingsText.ticketId.text = '0';
                this._settingsText.sessionId.text = '0';
            } else {
                this.updateTicketId();
            }
        } else if (requestType === 'Begin') {
            this.updateTicketId();
        }

        // if no session info has been provided don't forward on to the operator
        const syncSessionWithParent = gameConfig.features.syncSessionWithParent;
        if (syncSessionWithParent && requestType !== 'FromBingo') {
            inversifyContainer.frameConnection.operator.onSessionInfo({
                userId: userModel.userId,
                balance: userModel.totalBalance.startBalance,
                realBalance: 0, // TODO this is a value used by sisal, will need to be added once the arcade games are on the sisal network
                bonusBalance: 0, // TODO this is a value used by sisal, will need to be added once the arcade games are on the sisal network
                gameName: queryStringParams.currentSkin,
                version: gameConfig.version,
                sessionTime: 0, // TODO: leaving this as 0 for now as unused, may need adding later
                locale: getLocaleString(),
                managerStatus: status,
                managerSettings: settings,
            });
        }
    }

    private setSessionSettings(settingsData: Partial<SessionSettings>): void {
        this._settings = Object.assign(this._settings, settingsData);

        const sortNumber = (a: number, b: number) => a - b;
        this._settings.ValidMaxTimes.sort(sortNumber);
        this._settings.ValidMaxBets.sort(sortNumber).reverse();
        this._settings.ValidAlertFrequencies.sort(sortNumber).reverse();
        this._settings.ValidSessionRestrictions.sort(sortNumber);

        const percentages = [100, 75, 50, 25];

        if (this._settings.ValidMaxBets.length > percentages.length) {
            throw new Error('SessionModel.ValidMaxBets.Length - Valid max bets is longer than expected');
        }
    }

    private setSessionStatus(sessionData: Partial<SessionStatus>): void {
        this._status = Object.assign(this._status, sessionData);
        if (sessionData.PgdaSessionId) {
            this._settingsText.sessionId.text = this.status.PgdaSessionId;
            this.sessionDataEvents.emit('sessionIdUpdated', this._settingsText.sessionId.text);
        }
    }

    private onSessionCreated(response: IGameServerResponse): void {
        this.setData(response);
        this._settingsText.sessionId.text = this.status.PgdaSessionId;
        this.sessionDataEvents.emit('sessionIdUpdated', this._settingsText.sessionId.text);
    }

    private updateTicketId(): void {
        this._settingsText.ticketId.text = inversifyContainer.gameModel.gameId?.toString() ?? '0';
        this.sessionDataEvents.emit('ticketIdUpdated', this._settingsText.ticketId.text);
    }

    public getSessionToken(): string {
        if (this.sessionToken) {
            return this.sessionToken;
        }

        const userId = userModel.userId.toString();
        const timestamp = Date.now();
        const gameName = gameConfig.loggingName;
        const country = queryStringParams.locale.split('-')[1].toUpperCase();

        const components = `${userId}-${timestamp}-${gameName}-${country}`;

        const randomSuffix = Math.random().toString(36).substring(2, 8);

        this.sessionToken = `${components}-${randomSuffix}`;

        return this.sessionToken;
    }
}
export const sessionDataModel = new SessionDataModel();
